/**
 * UserPreferences — per-profile UI preferences.
 *
 * Lazily created: a Profile starts with no row; reads return defaults
 * derived by the caller (UI layer reads viewport width). The row is
 * upserted on first user-driven mutation.
 *
 * `updatedAt` is sourced from an injected clock to keep tests deterministic.
 */

import { sportSchema } from "@kaiord/core";
import { z } from "zod";

export const calendarViewSchema = z.enum(["grid", "list"]);

export type CalendarView = z.infer<typeof calendarViewSchema>;

export const unitsSchema = z.enum(["metric", "imperial"]);

export type Units = z.infer<typeof unitsSchema>;

/**
 * UI language preference. `auto` resolves the active locale from
 * `navigator.language` (see `resolve-locale`); `en`/`es` pin it explicitly.
 * Absent (pre-i18n rows) reads as `auto`.
 */
export const localePreferenceSchema = z.enum(["auto", "en", "es"]);

export type LocalePreference = z.infer<typeof localePreferenceSchema>;

export const userPreferencesSchema = z.object({
  profileId: z.string().min(1),
  calendarView: calendarViewSchema,
  // Optional: pre-v15 rows lack these fields. The Dexie v15 migration is
  // data-only; absence remains a valid state until the user first writes.
  lastScratchSport: sportSchema.optional(),
  /** Sport last selected on the Athlete page; absent until first chosen. */
  activeSport: sportSchema.optional(),
  aiBannerExpanded: z.boolean().optional(),
  /**
   * Legacy: `units`, `notificationsEnabled` and `locale` now live on the
   * device (`lib/device-preferences`); these are read once to seed it and
   * kept so older app versions syncing the same snapshot still work.
   */
  units: unitsSchema.optional(),
  /** User intent to enable browser notifications; absent defaults to off. */
  notificationsEnabled: z.boolean().optional(),
  /**
   * Parameter keys pinned to the F5 labs dashboard; absent means none
   * pinned yet. Optional and unindexed — no Dexie version bump (OQ2/S3).
   */
  labDashboardParams: z.array(z.string()).optional(),
  /** UI language preference; absent reads as `auto`. Optional, unindexed — no Dexie version bump. */
  locale: localePreferenceSchema.optional(),
  /**
   * User dismissed the "Getting set up" checklist. Absent reads as not
   * dismissed. Optional and unindexed — no Dexie version bump, and it rides
   * the cloud snapshot so the dismissal follows the profile across devices.
   */
  setupChecklistDismissed: z.boolean().optional(),
  /**
   * Coach-mark ids the profile already acted on or waved away. Absent reads
   * as "none seen yet". Optional and unindexed — no Dexie version bump — and
   * it rides the cloud snapshot, so a tip taught on one device stays taught.
   * Settings → "Show tips again" empties the array rather than deleting it.
   */
  dismissedCoachMarks: z.array(z.string()).optional(),
  updatedAt: z.iso.datetime(),
});

export type UserPreferences = z.infer<typeof userPreferencesSchema>;
